// Checked — caller MUST handle or declare it
void readFile(String path) throws IOException {
    Files.readString(Path.of(path));
}

void caller() {
    try {
        readFile("config.txt");
    } catch (IOException e) {
        // compiler-enforced: this can't be skipped
    }
}

// Unchecked — no declaration required, callers opt in to catching
void divide(int a, int b) {
    if (b == 0) throw new IllegalArgumentException("b must not be 0");
}

divide(1, 0); // compiles fine with no try/catch at all

// Old style — easy to get wrong, especially with 2+ resources
BufferedReader reader = null;
try {
    reader = new BufferedReader(new FileReader("data.txt"));
    System.out.println(reader.readLine());
} finally {
    if (reader != null) reader.close();
}

// try-with-resources — both closed automatically, in reverse order
try (var in = new FileReader("data.txt");
     var reader = new BufferedReader(in)) {
    System.out.println(reader.readLine());
} // reader.close() runs, then in.close()
catch (IOException e) {
    System.err.println("Failed: " + e.getMessage());
}

// Multi-catch — one handler for either failure mode
try {
    riskyIo();
    riskyDb();
} catch (IOException | SQLException e) {
    log.error("Operation failed", e);
}

// Exception chaining — the original cause is preserved
class RepositoryException extends RuntimeException {
    RepositoryException(String message, Throwable cause) {
        super(message, cause); // cause wired through, not dropped
    }
}

try {
    connection.query(sql);
} catch (SQLException e) {
    throw new RepositoryException("Failed to load user", e);
    // e.printStackTrace() on this later still shows the SQLException
}
